const DEFAULT_STATE = { habits: [] };

function pad2(n) {
  return n < 10 ? "0" + n : String(n);
}

function todayKey() {
  const d = new Date();
  return d.getFullYear() + "-" + pad2(d.getMonth() + 1) + "-" + pad2(d.getDate());
}

function todayLabel() {
  const d = new Date();
  const week = ["周日", "周一", "周二", "周三", "周四", "周五", "周六"][d.getDay()];
  return d.getFullYear() + " 年 " + (d.getMonth() + 1) + " 月 " + d.getDate() + " 日 · " + week;
}

function normalizeState(raw) {
  const base = raw && typeof raw === "object" ? raw : {};
  const next = Object.assign({}, base);
  const list = Array.isArray(base.habits) ? base.habits : [];
  next.habits = list.map(function (item) {
    const h = item && typeof item === "object" ? Object.assign({}, item) : {};
    if (typeof h.id !== "string" || !h.id) {
      h.id = "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
    }
    if (typeof h.name !== "string") h.name = String(h.name == null ? "" : h.name);
    if (typeof h.createdAt !== "string") h.createdAt = new Date().toISOString();
    const done = h.doneDates && typeof h.doneDates === "object" && !Array.isArray(h.doneDates) ? h.doneDates : {};
    const cleanDone = {};
    Object.keys(done).forEach(function (k) {
      if (done[k]) cleanDone[k] = true;
    });
    h.doneDates = cleanDone;
    return h;
  });
  return next;
}

function makeId() {
  return "h_" + Date.now().toString(36) + "_" + Math.random().toString(36).slice(2, 8);
}

function isDoneToday(habit, key) {
  return !!(habit && habit.doneDates && habit.doneDates[key]);
}

function countDoneToday(habits, key) {
  let n = 0;
  for (let i = 0; i < habits.length; i += 1) {
    if (isDoneToday(habits[i], key)) n += 1;
  }
  return n;
}

const els = {};
let state = normalizeState(null);
let pendingDeleteId = null;
let dialogResolver = null;

function cacheEls(app) {
  els.todayLabel = app.querySelector('[data-role="today-label"]');
  els.doneCount = app.querySelector('[data-role="done-count"]');
  els.totalCount = app.querySelector('[data-role="total-count"]');
  els.statsHint = app.querySelector('[data-role="stats-hint"]');
  els.progressFill = app.querySelector('[data-role="progress-fill"]');
  els.form = app.querySelector('[data-role="habit-form"]');
  els.input = app.querySelector('[data-role="habit-input"]');
  els.formError = app.querySelector('[data-role="form-error"]');
  els.list = app.querySelector('[data-role="habit-list"]');
  els.listCount = app.querySelector('[data-role="list-count"]');
  els.emptyTip = app.querySelector('[data-role="empty-tip"]');
  els.saveError = app.querySelector('[data-role="save-error"]');
  els.backdrop = app.querySelector('[data-role="dialog-backdrop"]');
  els.dialogTitle = app.querySelector('[data-role="dialog-title"]');
  els.dialogText = app.querySelector('[data-role="dialog-text"]');
  els.dialogCancel = app.querySelector('[data-role="dialog-cancel"]');
  els.dialogConfirm = app.querySelector('[data-role="dialog-confirm"]');
}

function renderStats() {
  const key = todayKey();
  const total = state.habits.length;
  const done = countDoneToday(state.habits, key);
  els.doneCount.textContent = String(done);
  els.totalCount.textContent = String(total);
  els.listCount.textContent = "共 " + total + " 个";
  const percent = total === 0 ? 0 : Math.round((done / total) * 100);
  els.progressFill.style.width = percent + "%";
  if (total === 0) {
    els.statsHint.textContent = "还没有习惯，先添加一个吧";
  } else if (done === total) {
    els.statsHint.textContent = "全部完成，今天很棒！";
  } else {
    els.statsHint.textContent = "还有 " + (total - done) + " 个习惯待完成";
  }
}

function renderList() {
  const key = todayKey();
  els.list.textContent = "";
  const habits = state.habits;
  els.emptyTip.hidden = habits.length > 0;

  habits.forEach(function (habit) {
    const li = document.createElement("li");
    li.className = "habit-item" + (isDoneToday(habit, key) ? " is-done" : "");
    li.setAttribute("data-habit-id", habit.id);

    const checkbox = document.createElement("input");
    checkbox.type = "checkbox";
    checkbox.className = "habit-check";
    checkbox.checked = isDoneToday(habit, key);
    checkbox.setAttribute("data-role", "toggle");
    checkbox.setAttribute("aria-label", "标记今天已完成：" + habit.name);
    checkbox.addEventListener("change", function () {
      toggleHabit(habit.id);
    });

    const name = document.createElement("span");
    name.className = "habit-name";
    name.textContent = habit.name;

    const meta = document.createElement("span");
    meta.className = "habit-meta";
    const doneTotal = Object.keys(habit.doneDates || {}).length;
    meta.textContent = "累计打卡 " + doneTotal + " 天";

    const del = document.createElement("button");
    del.type = "button";
    del.className = "habit-delete";
    del.setAttribute("data-role", "delete");
    del.textContent = "删除";
    del.addEventListener("click", function () {
      askDelete(habit.id);
    });

    li.appendChild(checkbox);
    li.appendChild(name);
    li.appendChild(meta);
    li.appendChild(del);
    els.list.appendChild(li);
  });
}

function renderAll() {
  renderStats();
  renderList();
}

function showSaveError(message) {
  els.saveError.textContent = message || "";
}

async function persist(nextState, errorMessage) {
  try {
    await appStore.setState(nextState);
    const check = await appStore.getState();
    state = normalizeState(check);
    showSaveError("");
    return true;
  } catch (err) {
    showSaveError(errorMessage || "保存失败，请重试。");
    return false;
  }
}

async function toggleHabit(id) {
  const key = todayKey();
  const next = normalizeState(state);
  const target = next.habits.filter(function (h) { return h.id === id; })[0];
  if (!target) {
    renderAll();
    return;
  }
  const done = Object.assign({}, target.doneDates);
  if (done[key]) {
    delete done[key];
  } else {
    done[key] = true;
  }
  target.doneDates = done;
  const ok = await persist(next, "打卡状态保存失败，请重试。");
  renderAll();
  if (!ok) {
    showSaveError("打卡状态保存失败，请重试。");
  }
}

async function addHabit(name) {
  const next = normalizeState(state);
  next.habits.push({
    id: makeId(),
    name: name,
    createdAt: new Date().toISOString(),
    doneDates: {}
  });
  const ok = await persist(next, "新增习惯保存失败，请重试。");
  renderAll();
  if (ok) {
    els.input.value = "";
    els.formError.textContent = "";
    els.input.focus();
  } else {
    showSaveError("新增习惯保存失败，请重试。");
  }
}

function openDialog(title, text, confirmLabel) {
  els.dialogTitle.textContent = title;
  els.dialogText.textContent = text;
  els.dialogConfirm.textContent = confirmLabel;
  els.backdrop.hidden = false;
  els.dialogConfirm.focus();
  return new Promise(function (resolve) {
    dialogResolver = resolve;
  });
}

function closeDialog(result) {
  els.backdrop.hidden = true;
  const resolve = dialogResolver;
  dialogResolver = null;
  if (resolve) resolve(result);
}

async function askDelete(id) {
  const target = state.habits.filter(function (h) { return h.id === id; })[0];
  if (!target) return;
  const targetId = target.id;
  const targetName = target.name;
  const confirmed = await openDialog(
    "确认删除",
    "确定要删除习惯「" + targetName + "」吗？该习惯的打卡记录也会一并删除，此操作不可撤销。",
    "确认删除"
  );
  if (!confirmed) return;
  const next = normalizeState(state);
  next.habits = next.habits.filter(function (h) { return h.id !== targetId; });
  const ok = await persist(next, "删除失败，请重试。");
  renderAll();
  if (!ok) {
    showSaveError("删除失败，请重试。");
  }
}

async function init() {
  const app = document.querySelector("#app");
  cacheEls(app);
  els.todayLabel.textContent = todayLabel();

  els.form.addEventListener("submit", function (event) {
    event.preventDefault();
    const value = els.input.value.trim();
    if (!value) {
      els.formError.textContent = "请输入习惯名称。";
      els.input.focus();
      return;
    }
    els.formError.textContent = "";
    addHabit(value);
  });

  els.dialogCancel.addEventListener("click", function () {
    closeDialog(false);
  });
  els.dialogConfirm.addEventListener("click", function () {
    closeDialog(true);
  });
  els.backdrop.addEventListener("click", function (event) {
    if (event.target === els.backdrop) closeDialog(false);
  });
  document.addEventListener("keydown", function (event) {
    if (event.key === "Escape" && !els.backdrop.hidden) closeDialog(false);
  });

  let raw = null;
  try {
    raw = await appStore.getState();
  } catch (err) {
    raw = null;
  }
  if (!raw || typeof raw !== "object" || !Array.isArray(raw.habits)) {
    const seeded = normalizeState(DEFAULT_STATE);
    try {
      await appStore.setState(seeded);
      const check = await appStore.getState();
      state = normalizeState(check);
    } catch (err) {
      state = seeded;
      showSaveError("初始化数据失败，当前更改可能无法保存。");
    }
  } else {
    state = normalizeState(raw);
  }

  renderAll();
}

await init();

