:root {
  --bg: #0f1c2e;
  --bg-soft: #16283f;
  --surface: #1c3350;
  --surface-2: #223c5d;
  --border: #2f4d72;
  --text: #eaf2fb;
  --text-dim: #9db4cd;
  --accent: #4fd1a5;
  --accent-strong: #2fb98c;
  --accent-soft: rgba(79, 209, 165, 0.16);
  --danger: #ff6b6b;
  --danger-soft: rgba(255, 107, 107, 0.14);
  --shadow: 0 18px 40px rgba(3, 10, 20, 0.45);
  --radius: 14px;
}

#app {
  min-height: 100vh;
  background: radial-gradient(1200px 600px at 15% -10%, #1d3b5c 0%, transparent 60%),
              radial-gradient(900px 500px at 100% 0%, #1a4a45 0%, transparent 55%),
              var(--bg);
  color: var(--text);
  font-family: "PingFang SC", "Hiragino Sans GB", "Microsoft YaHei", system-ui, -apple-system, sans-serif;
  font-size: 16px;
  line-height: 1.6;
  padding: 0;
  margin: 0;
  box-sizing: border-box;
}

#app *,
#app *::before,
#app *::after {
  box-sizing: border-box;
}

.app-shell {
  max-width: 720px;
  margin: 0 auto;
  padding: 32px 20px 64px;
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.app-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.app-title {
  margin: 0;
  font-size: 28px;
  letter-spacing: 2px;
  color: var(--text);
}

.app-subtitle {
  margin: 0;
  color: var(--text-dim);
  font-size: 14px;
}

.stats {
  position: relative;
  background: linear-gradient(160deg, var(--surface) 0%, var(--bg-soft) 100%);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px 26px;
  box-shadow: var(--shadow);
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 4px 18px;
  align-items: center;
}

.stats-main {
  display: flex;
  align-items: baseline;
  gap: 6px;
  font-variant-numeric: tabular-nums;
}

.stats-number {
  font-size: 44px;
  font-weight: 700;
  color: var(--accent);
  line-height: 1;
}

.stats-divider {
  font-size: 24px;
  color: var(--text-dim);
}

.stats-total {
  font-size: 24px;
  color: var(--text-dim);
}

.stats-text {
  display: flex;
  flex-direction: column;
}

.stats-title {
  margin: 0;
  font-size: 15px;
  color: var(--text);
}

.stats-hint {
  margin: 0;
  font-size: 13px;
  color: var(--text-dim);
}

.stats-bar {
  grid-column: 1 / -1;
  margin-top: 14px;
  height: 8px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.08);
  overflow: hidden;
}

.stats-bar-fill {
  height: 100%;
  width: 0%;
  border-radius: 999px;
  background: linear-gradient(90deg, var(--accent-strong), var(--accent));
  transition: width 0.25s ease;
}

.panel {
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 20px 22px;
  box-shadow: var(--shadow);
}

.panel-head {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 12px;
}

.panel-title {
  margin: 0 0 12px;
  font-size: 17px;
  color: var(--text);
}

.panel-head .panel-title {
  margin-bottom: 0;
}

.panel-count {
  font-size: 13px;
  color: var(--text-dim);
}

.habit-form {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  align-items: flex-end;
}

.field {
  flex: 1 1 240px;
  display: flex;
  flex-direction: column;
  gap: 6px;
}

.field-label {
  font-size: 13px;
  color: var(--text-dim);
}

.field-input {
  width: 100%;
  padding: 11px 14px;
  font-size: 15px;
  font-family: inherit;
  color: var(--text);
  background: var(--bg-soft);
  border: 1px solid var(--border);
  border-radius: 10px;
  outline: none;
  transition: border-color 0.2s ease, box-shadow 0.2s ease;
}

.field-input::placeholder {
  color: #6f88a3;
}

.field-input:focus {
  border-color: var(--accent);
  box-shadow: 0 0 0 3px var(--accent-soft);
}

.btn {
  font-family: inherit;
  font-size: 15px;
  padding: 11px 20px;
  border-radius: 10px;
  border: 1px solid transparent;
  cursor: pointer;
  transition: transform 0.12s ease, background 0.2s ease, border-color 0.2s ease, color 0.2s ease;
}

.btn:active {
  transform: translateY(1px);
}

.btn-primary {
  background: var(--accent);
  color: #06231a;
  font-weight: 600;
}

.btn-primary:hover {
  background: var(--accent-strong);
}

.btn-ghost {
  background: transparent;
  color: var(--text-dim);
  border-color: var(--border);
}

.btn-ghost:hover {
  color: var(--text);
  border-color: var(--text-dim);
}

.btn-danger {
  background: var(--danger);
  color: #2b0707;
  font-weight: 600;
}

.btn-danger:hover {
  background: #ff5252;
}

.form-error {
  flex: 1 1 100%;
  margin: 0;
  min-height: 18px;
  font-size: 13px;
  color: var(--danger);
}

.habit-list {
  list-style: none;
  margin: 14px 0 0;
  padding: 0;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.habit-item {
  display: flex;
  align-items: center;
  gap: 14px;
  padding: 12px 14px;
  background: var(--surface-2);
  border: 1px solid var(--border);
  border-radius: 12px;
  transition: border-color 0.2s ease, background 0.2s ease;
}

.habit-item.is-done {
  border-color: var(--accent);
  background: linear-gradient(90deg, var(--accent-soft), var(--surface-2) 70%);
}

.habit-check {
  flex: 0 0 auto;
  width: 26px;
  height: 26px;
  accent-color: var(--accent);
  cursor: pointer;
}

.habit-name {
  flex: 1 1 auto;
  font-size: 16px;
  color: var(--text);
  word-break: break-word;
}

.habit-item.is-done .habit-name {
  color: var(--accent);
}

.habit-meta {
  flex: 0 0 auto;
  font-size: 12px;
  color: var(--text-dim);
  white-space: nowrap;
}

.habit-delete {
  flex: 0 0 auto;
  font-family: inherit;
  font-size: 13px;
  padding: 7px 12px;
  border-radius: 9px;
  border: 1px solid transparent;
  background: var(--danger-soft);
  color: var(--danger);
  cursor: pointer;
  transition: background 0.2s ease, color 0.2s ease;
}

.habit-delete:hover {
  background: var(--danger);
  color: #2b0707;
}

.empty-tip {
  margin: 14px 0 0;
  font-size: 14px;
  color: var(--text-dim);
}

.empty-tip[hidden] {
  display: none;
}

.save-error {
  margin: 0;
  min-height: 20px;
  font-size: 13px;
  color: var(--danger);
}

.dialog-backdrop {
  position: fixed;
  inset: 0;
  background: rgba(4, 10, 18, 0.68);
  display: flex;
  align-items: center;
  justify-content: center;
  padding: 20px;
  z-index: 50;
}

.dialog-backdrop[hidden] {
  display: none;
}

.dialog {
  width: 100%;
  max-width: 380px;
  background: var(--surface);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 22px;
  box-shadow: var(--shadow);
}

.dialog-title {
  margin: 0 0 10px;
  font-size: 18px;
  color: var(--text);
}

.dialog-text {
  margin: 0 0 20px;
  font-size: 14px;
  color: var(--text-dim);
  word-break: break-word;
}

.dialog-actions {
  display: flex;
  justify-content: flex-end;
  gap: 10px;
}

@media (max-width: 480px) {
  .app-shell {
    padding: 22px 14px 48px;
  }

  .stats-number {
    font-size: 36px;
  }

  .habit-item {
    flex-wrap: wrap;
  }

  .habit-name {
    flex: 1 1 100%;
    order: 2;
  }
}
